//! 🧪️ Real cancellation root allocation refusal retains the same node and actual marker.
use semio_framework_async::{OriginalCancelRootAdmission,CancelTokenRetirement};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneStep,RetainedWorkOutcome,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet,RetainedWorkPoll};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn complete(result:RetainedWorkOutcome)->RetainedWorkPoll<RetainedCloneStep,ValueError>{RetainedWorkPoll::Complete(result)}
fn take(turn:RetainedWorkPoll<RetainedCloneStep,ValueError>)->RetainedWorkOutcome{let RetainedWorkPoll::Complete(turn)=turn else{panic!("original cancellation birth unexpectedly pending")};turn}
#[test]fn real_root_allocator_refusal_preserves_original_node_and_marker(){
 let law:serde_json::Value=serde_json::from_str(include_str!("resident.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":64,"copyBytes":1048576,"capacityBytes":1048576,"releaseBytes":1048576,"depth":64,"fuel":128})));let mut owner=OriginalCancelRootAdmission::new();
 let issued=grant(OriginalCancelRootAdmission::prepare_demand());let(turn,actual)=bank.run(issued,1,|effect|complete(owner.prepare(effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));assert!(owner.has_input());
 let issued=grant(OriginalCancelRootAdmission::backing_demand().unwrap());let(((turn,actual),attempts),heap)=observe(||refuse(||bank.run(issued,OriginalCancelRootAdmission::backing_work_demand(),|effect|complete(owner.admit_backing(effect)))));let turn=take(turn);assert_eq!(attempts,1);assert_eq!(actual,Some(law[1]["actual"].as_u64().unwrap()as usize));assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(owner.has_input(),law[1]["input"].as_bool().unwrap());assert!(!owner.has_backing());assert_eq!(bank.take_admitted(),Some(true));
 let((turn,actual),heap)=observe(||bank.run(issued,OriginalCancelRootAdmission::backing_work_demand(),|effect|complete(owner.admit_backing(effect))));let turn=take(turn);assert_eq!(actual,Some(issued.maximum_capacity_bytes));let identity=owner.backing_identity().unwrap();bank.post(turn.result.unwrap().progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));
 let issued=grant(OriginalCancelRootAdmission::publication_demand().unwrap());let(turn,actual)=bank.run(issued,OriginalCancelRootAdmission::publication_work_demand(),|effect|complete(owner.publish(effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));let issued=grant(OriginalCancelRootAdmission::take_demand());let mut output=None;let(turn,actual)=bank.run(issued,1,|effect|complete(owner.take_token(&mut output,effect)));let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));assert_eq!(OriginalCancelRootAdmission::token_identity(output.as_ref().unwrap()),identity);assert!(owner.terminal_is_empty());
 let mut retired=None;let prepare=RetirementDemand{copy_bytes:std::mem::size_of::<Option<semio_framework_async::CancelToken>>()+std::mem::size_of::<Option<CancelTokenRetirement>>(),depth:1,..Default::default()};let issued=grant(prepare);let(turn,actual)=bank.run(issued,1,|effect|{assert!(effect.performed(1).unwrap());retired=Some(CancelTokenRetirement::from_token(output.take().unwrap()));complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:prepare.copy_bytes,..Default::default()})),work:1})});let turn=take(turn);assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,(0,0));assert_eq!(bank.take_admitted(),Some(true));for _ in 0..16{let retired=retired.as_mut().unwrap();if retired.terminal_is_empty(){break}let issued=grant(retired.retirement_demands().unwrap());let work=retired.retirement_work_demand().unwrap();let((turn,actual),heap)=observe(||bank.run(issued,work,|effect|RetainedWorkPoll::Complete(retired.close_step(effect))));let RetainedWorkPoll::Complete(turn)=turn else{panic!("original cancellation close pending")};assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));}assert!(retired.as_ref().unwrap().terminal_is_empty());
}
